import {useRef, useState, useEffect, useContext} from 'react'

import '../styles/Map.scss'
import {data, stations, counties, virginiaCounties} from '../data'
import {OptionsContext} from '../contexts/OptionsContext'
// import {ChartContext} from '../contexts/ChartContext'
// import {CurrentContext} from '../contexts/CurrentContext'

function MapIE() {
  const mapContainerRef = useRef(null);
  // const [popup, setPopup] = useState(null)
  // const [tooltip, setTooltip] = useState(null)
  // const [countyFilter, setCountyFilter] = useState(counties)

  const {options: {emission, rp, tp, area}} = useContext(OptionsContext)

  const currentData = data[emission][tp][rp]

  let max = Math.ceil(currentData.max*10)/10
  let min = Math.floor(currentData.min*10)/10

  max = Math.round((1+Math.max(max-1, 1-min))*10)/10;
  min = Math.round((1-Math.max(max-1, 1-min))*10)/10;

  useEffect(() => {
    const L = window.L;
    L.mapbox.accessToken = 'pk.eyJ1IjoiYmVuZWNrIiwiYSI6ImNrbTBvNWNtdTB1eXUyb21yeWhpbWZrYWMifQ.rSYtPIiS9ZbnnCdSbtm4wQ';

    var map = L.mapbox.map(mapContainerRef.current)
        .setView([40, -74.50], 9)
        .addLayer(L.mapbox.styleLayer('mapbox://styles/mapbox/streets-v11'));

    // map.on("load", () => {
    //   // add the data source for new a feature collection with no features
    //   map.addSource("random-points-data", {
    //     type: "geojson",
    //     data: {
    //       type: "FeatureCollection",
    //       features: []
    //     }
    //   });
    //   // now add the layer, and reference the data source above by name
    //   map.addLayer({
    //     id: "random-points-layer",
    //     source: "random-points-data",
    //     type: "symbol",
    //     layout: {
    //       // full list of icons here: https://labs.mapbox.com/maki-icons
    //       "icon-image": "bakery-15", // this will put little croissants on our map
    //       "icon-padding": 0,
    //       "icon-allow-overlap": true
    //     }
    //   });
    // });

    return () => map.remove();
  }, []);

  const mapStyle = {
    height: "100%",
    width: "100%",
    overflow: "hidden"
  }

  return <div className="map-container" style={mapstyle} ref={mapContainerRef} />;
}

export default MapIE;
